UPDATE `#__guidedtours` SET `autostart` = 0;
INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Bloqueo de un artículo', 'joomlaguide-locking-an-article-es', '<p>Cuando alguien edita un artículo, Joomla lo <em>bloquea</em>: nadie más puede cambiarlo al mismo tiempo. Al guardar o cerrar el artículo, se <em>desbloquea</em> de nuevo.</p><p>Si quien edita se va sin guardar ni cerrar, el artículo se queda bloqueado. En este recorrido ves cómo pasa eso y cómo lo desbloquea un administrador.</p><p>Este recorrido sigue el tutorial <a href="https://guide.joomla.org/es/tutoriales/gestion-de-contenido/7-publicacion-y-acceso/7-5-bloqueo-de-un-articulo" target="_blank" rel="noopener">7.5 Bloqueo de un artículo</a> de la Guía del usuario de Joomla.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 7.5 Locking an Article', 1, 1);
INSERT INTO `#__guidedtour_steps` (`tour_id`, `title`, `description`, `ordering`, `position`, `target`, `type`, `interactive_type`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `params`) VALUES
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-es'), 'Contenido', '<p>En el menú de la izquierda, haz clic en <strong>Contenido</strong>.</p><p>Se abre y muestra lo que puedes hacer allí.</p>', 1, 'right', 'body.com_cpanel #sidebarmenu li.item-level-1:has(a[href="index.php?option=com_content&view=articles"]) > a.has-arrow', 2, 4, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-es'), 'Contenido › Artículos', '<p>Haz clic en <strong>Artículos</strong>, en <strong>Contenido</strong>.</p>', 2, 'right', 'body.com_cpanel #sidebarmenu a[href="index.php?option=com_content&view=articles"]', 2, 1, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-es'), 'Abrir el artículo', '<p>Haz clic en <strong>El ayuntamiento aprueba un nuevo presupuesto de transporte</strong> para editarlo.</p>', 3, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" El ayuntamiento aprueba un nuevo presupuesto de transporte"]) a[href*="task=article.edit"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-es'), 'Salir sin cerrar', '<p>Ahora estás editando el artículo. No hagas clic en <strong>Guardar</strong> ni en <strong>Cerrar</strong>: pulsa el botón <em>Atrás</em> de tu navegador. Es lo que hace alguien que se va sin cerrar.</p><p>De vuelta en la lista, el artículo tiene un candado: está bloqueado. Pasa el ratón por encima del candado para ver quién lo bloqueó y cuándo. (¿No hay candado? Recarga la página.)</p>', 4, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" El ayuntamiento aprueba un nuevo presupuesto de transporte"]) th', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-es'), '¿Quién puede editarlo?', '<p>Tú bloqueaste el artículo, así que todavía puedes abrirlo. Los demás usuarios, incluso los administradores, reciben un mensaje de error si lo intentan.</p><p>Cuando haces clic en <strong>Cerrar</strong> o <strong>Guardar y cerrar</strong> en el artículo, se desbloquea de nuevo.</p>', 5, 'bottom', '#articleList tr:has(a[href*="task=article.edit"][title$=" El ayuntamiento aprueba un nuevo presupuesto de transporte"])', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-es'), 'Desbloquear el artículo', '<p>Aquí quien editaba no ha vuelto. Como administrador puedes desbloquear el artículo: haz clic en el candado.</p>', 6, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" El ayuntamiento aprueba un nuevo presupuesto de transporte"]) [data-item-task="articles.checkin"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-es'), '¡Bien hecho!', '<p>El artículo está desbloqueado, y cualquiera con permiso puede volver a editarlo.</p><p>Para desbloquear muchos artículos a la vez, marca sus casillas y elige <strong>Acciones</strong> › <strong>Desbloqueo</strong>.</p><p>Ten cuidado: si la persona que edita sigue trabajando en el artículo, sus cambios pueden perderse.</p>', 7, 'bottom', '#system-message-container', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL);
